package com.massivex.android.transfer

import com.massivex.android.wallet.*
import kotlinx.coroutines.*
import org.junit.Assert.*
import org.junit.Test
import java.io.IOException

class SendCoordinatorTest {
    @Test fun injectedDisabledTransportStopsBeforeAuthKeyAccessOrIntent()=runBlocking{val h=TransferHarness(broadcast=NoBroadcastTransport).start();h.send();assertEquals(SendError.DISABLED,h.coordinator.state.value.error);assertTrue(h.auth.actions.isEmpty());assertTrue(h.ledger.records().isEmpty());assertFalse(h.coordinator.submissionEnabled)}
    @Test fun noBroadcastAdapterAlwaysThrows()=runBlocking{try{NoBroadcastTransport.submit(signed());fail("Broadcast enabled")}catch(e:SendFailure){assertEquals(SendError.DISABLED,e.reason)}}
    @Test fun happyFakeResponseMeansPendingOnlyAndJournalPrecedesTransport()=runBlocking{
        val t=RecordingTransport();val h=TransferHarness(broadcast=t).start()
        t.callback={s->assertEquals(listOf(TransferState.SIGNED,TransferState.SUBMIT_ATTEMPT),h.disk.states);assertEquals(s.binding,h.record().signed.binding);BroadcastReply.Accepted(s.draft.operationId)}
        h.send();assertEquals(1,t.calls);assertEquals(TransferState.PENDING,h.record().state);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)));assertEquals(Purpose.SIGN,h.auth.actions.single().purpose)
    }
    @Test fun exactDraftCommitmentReachesFreshApproval()=runBlocking{val h=TransferHarness().start();h.prepare();val d=h.coordinator.state.value.review!!;h.coordinator.confirm(d,h.signer);assertEquals(d.commitment,h.auth.actions.single().commitment);assertEquals(h.wallet.id,h.auth.actions.single().walletId)}
    @Test fun differentReviewedApprovalRejected()=runBlocking{val h=TransferHarness().start();h.prepare();h.coordinator.confirm(review(),h.signer);assertEquals(SendError.CHANGED,h.coordinator.state.value.error);assertTrue(h.auth.actions.isEmpty());assertTrue(h.ledger.records().isEmpty())}
    @Test fun changedFeeBeforeAuthInvalidatesReview()=runBlocking{val h=TransferHarness().start();h.prepare();h.snapshotValue=h.snapshotValue.copy(fee=com.massivex.massa.MASAmount(2uL));h.coordinator.confirm(h.coordinator.state.value.review,h.signer);assertEquals(SendError.CHANGED,h.coordinator.state.value.error);assertNull(h.coordinator.state.value.review);assertTrue(h.auth.actions.isEmpty())}
    @Test fun changedBalanceAfterAuthPreventsJournal()=runBlocking{val h=TransferHarness().start();h.preflightHook={call->h.snapshotValue.copy(fetchedAt=h.now,finalBalance=if(call==3)com.massivex.massa.MASAmount(9_000_000_000uL)else h.snapshotValue.finalBalance)};h.send();assertEquals(SendError.CHANGED,h.coordinator.state.value.error);assertEquals(1,h.auth.actions.size);assertTrue(h.ledger.records().isEmpty())}
    @Test fun expiredReviewDoesNotPrompt()=runBlocking{val h=TransferHarness().start();h.prepare();h.now+=20001;h.coordinator.confirm(h.coordinator.state.value.review,h.signer);assertEquals(SendError.STALE,h.coordinator.state.value.error);assertTrue(h.auth.actions.isEmpty())}
    @Test fun authThatOutlivesReviewCannotPersistOrTransmit()=runBlocking{val h=TransferHarness().start();h.auth.intercept={h.now+=20001};h.send();assertTrue(h.ledger.records().isEmpty());assertEquals(0,(h.broadcast as RecordingTransport).calls)}
    @Test fun authCancelDenyAndExpiryNeverSubmit()=runBlocking{for(reason in listOf(WalletError.CANCELLED,WalletError.AUTH,WalletError.EXPIRED)){val h=TransferHarness().start();h.auth.denied=reason;h.send();assertTrue(h.ledger.records().isEmpty());assertEquals(0,(h.broadcast as RecordingTransport).calls)}}
    @Test fun wrongApprovalBindingNeverSigns()=runBlocking{val h=TransferHarness().start();h.auth.wrongBinding=true;h.send();assertTrue(h.ledger.records().isEmpty());assertEquals(0,(h.broadcast as RecordingTransport).calls)}
    @Test fun walletSelectionCannotRebindDuringAuth()=runBlocking{val h=TransferHarness().start();h.auth.intercept={h.coordinator.select(source(44))};h.send();assertTrue(h.ledger.records().isEmpty());assertEquals(source(44),h.coordinator.state.value.source)}
    @Test fun underlyingCatalogSelectionChangeBeforeDecryptRejected()=runBlocking{
        val h=TransferHarness().start();val watch=h.repository.addWatch(recipient,"Other").selected!!;h.repository.select(h.wallet.id)
        h.auth.intercept={val old=CatalogCodec.decode(h.catalog.bytes!!);h.catalog.write(CatalogCodec.encode(old.copy(selectedId=watch.id)))}
        h.send();assertTrue(h.ledger.records().isEmpty());assertEquals(0,(h.broadcast as RecordingTransport).calls)
    }
    @Test fun backgroundDuringAuthRevokesWithoutTransmission()=runBlocking{val h=TransferHarness().start();h.auth.intercept={h.coordinator.stop()};h.send();assertTrue(h.ledger.records().isEmpty());assertEquals(0,(h.broadcast as RecordingTransport).calls)}
    @Test fun duplicateConfirmationOnlyOneAuthAndTransport()=runBlocking{
        val h=TransferHarness().start();h.prepare();val d=h.coordinator.state.value.review!!;val entered=CompletableDeferred<Unit>();val release=CompletableDeferred<Unit>()
        h.auth.intercept={entered.complete(Unit);release.await()}
        val first=launch{h.coordinator.confirm(d,h.signer)};entered.await();h.coordinator.confirm(d,h.signer);release.complete(Unit);first.join()
        assertEquals(1,h.auth.actions.size);assertEquals(1,(h.broadcast as RecordingTransport).calls);assertEquals(1,h.ledger.records().size)
    }
    @Test fun concurrentCoordinatorsCannotClaimSameSource()=runBlocking{
        val h=TransferHarness().start();h.prepare();val second=SendCoordinator(h.reader,h.ledger,h.finality,h.broadcast,{h.now},{h.now+=it});second.select(TransferSource.capture(h.wallet));second.resume();second.prepare(recipient,"2")
        val entered=CompletableDeferred<Unit>();val release=CompletableDeferred<Unit>();h.auth.intercept={entered.complete(Unit);release.await()}
        val job=launch{h.coordinator.confirm(h.coordinator.state.value.review,h.signer)};entered.await()
        val signer=object:TransferSigner{override suspend fun sign(draft:ReviewedTransfer)=signed(draft);override fun cancel(){}}
        second.confirm(second.state.value.review,signer);assertEquals(SendError.LOCKED,second.state.value.error);release.complete(Unit);job.join();assertEquals(1,(h.broadcast as RecordingTransport).calls)
    }
    @Test fun repeatedSwipeAfterPendingCannotResend()=runBlocking{val h=TransferHarness().start();h.send();h.coordinator.confirm(null,h.signer);h.coordinator.prepare(recipient,"1");assertEquals(1,(h.broadcast as RecordingTransport).calls);assertEquals(SendError.LOCKED,h.coordinator.state.value.error)}
    @Test fun rejectedResponseStaysUnknownAndLocked()=runBlocking{val t=RecordingTransport().apply{callback={BroadcastReply.Rejected}};val h=TransferHarness(broadcast=t).start();h.send();assertEquals(TransferState.UNKNOWN,h.record().state);assertEquals(TransferNote.REJECTED_UNVERIFIED,h.record().note);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)))}
    @Test fun missingAndMalformedReceiptCannotFinalize()=runBlocking{for(reply in listOf(BroadcastReply.Missing,BroadcastReply.Accepted("not-an-operation"))){val t=RecordingTransport().apply{callback={reply}};val h=TransferHarness(broadcast=t).start();h.send();assertEquals(TransferState.UNKNOWN,h.record().state);assertEquals(1,t.calls)}}
    @Test fun lostResponseAfterAdapterAcceptedRemainsUnknown()=runBlocking{val t=RecordingTransport().apply{callback={throw IOException("PUBLIC fake lost response")}};val h=TransferHarness(broadcast=t).start();h.send();assertEquals(TransferState.UNKNOWN,h.record().state);assertEquals(1,t.calls)}
    @Test fun timeoutAfterAttemptRemainsUnknown()=runBlocking{val t=RecordingTransport().apply{callback={throw java.net.SocketTimeoutException()}};val h=TransferHarness(broadcast=t).start();h.send();assertEquals(TransferState.UNKNOWN,h.record().state);assertEquals(1,t.calls)}
    @Test fun midCallCancellationKeepsDurableLock()=runBlocking{val t=RecordingTransport().apply{callback={throw CancellationException("synthetic")}};val h=TransferHarness(broadcast=t).start();try{h.send()}catch(_:CancellationException){};assertEquals(TransferState.UNKNOWN,TransferLedger(h.disk).records().single().state);assertEquals(1,t.calls)}
    @Test fun processDeathAtTransportEntryKeepsAttemptForRestart()=runBlocking{val t=RecordingTransport().apply{callback={throw AssertionError("PUBLIC synthetic process death")}};val h=TransferHarness(broadcast=t).start();try{h.send()}catch(_:AssertionError){};val r=TransferLedger(h.disk).records().single();assertEquals(TransferState.SUBMIT_ATTEMPT,r.state);assertNotNull(TransferLedger(h.disk).pending(r.signed.draft.source))}
    @Test fun journalFailureBeforeSignedOrBeforeAttemptForbidsTransport()=runBlocking{for(write in listOf(1,2)){val h=TransferHarness().start();h.disk.failWrite=write;h.send();assertEquals(0,(h.broadcast as RecordingTransport).calls);assertEquals(SendError.JOURNAL,h.coordinator.state.value.error);if(write==2)assertEquals(TransferState.SIGNED,TransferLedger(h.disk).records().single().state)}}
    @Test fun ambiguousSignedCommitForbidsTransportAndKeepsLock()=runBlocking{val h=TransferHarness().start();h.disk.commitThenFail=1;h.send();assertEquals(0,(h.broadcast as RecordingTransport).calls);assertNotNull(TransferLedger(h.disk).pending(TransferSource.capture(h.wallet)))}
    @Test fun pendingCommitFailureAfterResponseCannotUnlock()=runBlocking{val h=TransferHarness().start();h.disk.failWrite=3;h.send();assertEquals(1,(h.broadcast as RecordingTransport).calls);assertNotNull(TransferLedger(h.disk).pending(TransferSource.capture(h.wallet)))}
    @Test fun restartNeverRebroadcastsSignedOrUnknownIntent()=runBlocking{val h=TransferHarness().start();h.send();val reopened=SendCoordinator(h.reader,TransferLedger(h.disk),h.finality,h.broadcast,{h.now},{h.now+=it});reopened.select(TransferSource.capture(h.wallet));reopened.resume();reopened.reload();reopened.pollSelected();assertEquals(1,(h.broadcast as RecordingTransport).calls);assertEquals(8,h.finality.observeCalls);assertNotNull(reopened.state.value.pending)}
    @Test fun walletSwitchAfterAdapterCallKeepsOriginalSourceLock()=runBlocking{val t=RecordingTransport();val h=TransferHarness(broadcast=t).start();t.callback={s->h.coordinator.select(source(44));BroadcastReply.Accepted(s.draft.operationId)};h.send();assertEquals(source(44),h.coordinator.state.value.source);assertNull(h.coordinator.state.value.pending);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)));h.ledger.acquire(source(44)).close()}
    @Test fun duplicateCallbacksResolveOneDeferredResponseOnly()=runBlocking{var calls=0;val adapter=object:BroadcastTransport{override val enabled=true;override suspend fun submit(signed:SignedTransfer):BroadcastReply{calls++;val once=CompletableDeferred<BroadcastReply>();assertTrue(once.complete(BroadcastReply.Accepted(signed.draft.operationId)));assertFalse(once.complete(BroadcastReply.Rejected));return once.await()}};val h=TransferHarness(broadcast=adapter).start();h.send();assertEquals(1,calls);assertEquals(TransferState.PENDING,h.record().state)}
    @Test fun invalidSignerCannotPersistAnything()=runBlocking{val h=TransferHarness().start();h.prepare();val bad=object:TransferSigner{override suspend fun sign(draft:ReviewedTransfer)=SignedTransfer(draft,"bad");override fun cancel(){}};h.coordinator.confirm(h.coordinator.state.value.review,bad);assertEquals(SendError.SIGNATURE,h.coordinator.state.value.error);assertTrue(h.ledger.records().isEmpty())}
    @Test fun samePeriodExactTerminalOperationNotResubmitted()=runBlocking{val h=TransferHarness().start();h.send();h.finality.final();h.coordinator.reconcile(h.record().operationId);assertNull(h.ledger.pending(TransferSource.capture(h.wallet)));h.coordinator.prepare(recipient,"1");assertEquals(SendError.DUPLICATE,h.coordinator.state.value.error);assertEquals(1,(h.broadcast as RecordingTransport).calls)}
    @Test fun maxUsesPreflightAndDoesNotAuthorize()=runBlocking{val h=TransferHarness().start();h.coordinator.maximum(recipient);assertEquals("8.999",h.coordinator.state.value.maximum);assertTrue(h.auth.actions.isEmpty());assertTrue(h.ledger.records().isEmpty())}
    @Test fun ownedDecryptedSeedBufferClearedAfterSigning()=runBlocking{val h=TransferHarness().start();var seed:ByteArray?=null;val wrapping=object:SecretStorage by h.secrets{override fun decrypt(wallet:Wallet)=h.secrets.decrypt(wallet).also{seed=it}};val repo=WalletRepository(h.catalog,wrapping,Randomness{throw AssertionError("No random seed")},h.auth,removalGuard=h.ledger);h.prepare();h.coordinator.confirm(h.coordinator.state.value.review,ProtectedWalletSigner(repo,h.auth){h.now});assertNotNull(seed);assertTrue(seed!!.all{it==0.toByte()});assertEquals(1,(h.broadcast as RecordingTransport).calls)}
    @Test fun signatureForAnotherReviewedUuidCannotBeSubstituted()=runBlocking{val h=TransferHarness().start();h.prepare();val d=h.coordinator.state.value.review!!;val changed=ReviewedTransfer.restore(d.reviewId,d.source.copy(walletId=java.util.UUID.randomUUID().toString()),d.recipient,d.amount,d.snapshot,d.expiry,d.reviewedAt);val fake=object:TransferSigner{override suspend fun sign(draft:ReviewedTransfer)=signed(changed);override fun cancel(){}};h.coordinator.confirm(d,fake);assertTrue(h.ledger.records().isEmpty());assertEquals(SendError.SIGNATURE,h.coordinator.state.value.error)}
    @Test fun removalLeaseBeatsConcurrentSigning()=runBlocking{val h=TransferHarness().start();h.prepare();val entered=CompletableDeferred<Unit>();val release=CompletableDeferred<Unit>();h.auth.intercept={if(it.purpose==Purpose.REMOVE){entered.complete(Unit);release.await()}};val deleting=async{h.repository.remove(h.wallet.id,true)};entered.await();h.coordinator.confirm(h.coordinator.state.value.review,h.signer);assertEquals(SendError.LOCKED,h.coordinator.state.value.error);release.complete(Unit);assertTrue(deleting.await().wallets.isEmpty());assertEquals(0,(h.broadcast as RecordingTransport).calls)}

    @Test fun stoppedFormPreviewAndMaximumCannotStartBackgroundReads()=runBlocking{
        val h=TransferHarness().start();h.coordinator.stop()
        h.coordinator.preview(recipient);h.coordinator.maximum(recipient)
        assertEquals(0,h.preflightCalls);assertTrue(h.auth.actions.isEmpty());assertTrue(h.ledger.records().isEmpty())
    }

}
